function maxSumAfterOperation(nums) {
  let plain = 0;
  let squared = 0;
  let best = 0;

  for (const value of nums) {
    squared = Math.max(squared + value, plain + value * value);
    plain = Math.max(plain + value, 0);
    best = Math.max(best, squared);
  }
  return best;
}

