  let best = -Infinity;
  for (let pick = 0; pick < nums.length; pick++) {
    const changed = nums.slice();
    changed[pick] = nums[pick] * nums[pick];
    for (let start = 0; start < changed.length; start++) {
      let total = 0;
      for (let end = start; end < changed.length; end++) {
        total += changed[end];
        if (total > best) best = total;
      }
    }
  }
  return best;
}

