function generate(rand, size) {
  const limit = 10000;
  if (size === 'large') {
    const n = 2000;
    return [Array.from({ length: n }, () => Math.floor(rand() * (2 * limit + 1)) - limit)];
  }
  const n = 1 + Math.floor(rand() * 8);
  const span = rand() < 0.5 ? 4 : 30;
  const nums = Array.from({ length: n }, () => {
    const roll = rand();
    if (roll < 0.05) return -limit;
    if (roll < 0.1) return limit;
    if (roll < 0.15) return 0;
    return Math.floor(rand() * (2 * span + 1)) - span;
  });
  return [nums];
}
